files = {}

for path, old_b64, new_b64, label in patches:
    p = Path(path)
    if not p.exists():
        raise SystemExit(f"Missing {path}")

    text = files.get(
        path,
        p.read_text(encoding="utf-8"),
    )
    old = base64.b64decode(
        old_b64
    ).decode("utf-8")
    new = base64.b64decode(
        new_b64
    ).decode("utf-8")

    count = text.count(old)

    if count != 1:
        raise SystemExit(
            f"{label}: expected 1 match, found {count}. "
            f"Patch expects exact baseline {BASE}."
        )

    files[path] = text.replace(
        old,
        new,
        1,
    )

css_path = Path("app/globals.css")
if not css_path.exists():
    raise SystemExit("Missing app/globals.css")

css = css_path.read_text(
    encoding="utf-8",
)
addition = base64.b64decode(
    ""
).decode("utf-8")

marker = "SEPULCHRIA MOBILE COMPACT CONTENT"

if marker not in css:
    css = css.rstrip() + "\n" + addition
    files[str(css_path)] = css

for path, text in files.items():
    Path(path).write_text(
        text,
        encoding="utf-8",
    )
    print("✓", path)

